const normalizeReferenceName = (name) => String(name || "")
    .toLocaleLowerCase("ru-RU")
    .replace(/ё/g, "е")
    .replace(/\s*\[[^\]]+\]\s*$/, "")
    .replace(/\s+/g, " ")
    .trim();

const normalizedReferenceDescriptions = Object.fromEntries(
    Object.entries(referenceDescriptionsData).map(([name, description]) => [normalizeReferenceName(name), description])
);

export function getReferenceDescription(name, fallback = "") {
    return referenceDescriptionsData[name]
        || normalizedReferenceDescriptions[normalizeReferenceName(name)]
        || fallback;
}
